mapper.select:
SELECT device_code AS item, COUNT(id) AS cnt
FROM alarm_event
WHERE del_flag = 0

    AND alarm_time >= #{startTime}


    AND alarm_time < #{endTime}


    AND dept_code LIKE

        #{factoryCode} || '%'


        CONCAT(#{factoryCode}, '%')


GROUP BY device_code

    ORDER BY ${orderBy}


    LIMIT ${limit}
